export { authMail, mail, mailFrom, sendMail, smtpUrl, mailStartup } from "./mail.server";
export type { Mail } from "./mail.server";

export { smtpSockets } from "./sockets.server";

export { mailSendTimeout } from "./settings";

export { mailOutbox } from "./schema.server";
export { enqueueMail } from "./mail.server";

export {
  claimMailBatch,
  acknowledgeMail,
  releaseMailClaims,
  deliverMailBatch,
  outboxWake,
  mailWorkerStop,
  mailLeaseMs,
} from "./delivery.server";

export { runMailWorker } from "./delivery.server";

import { extension, operation, resource } from "@tinker/core";
import { z } from "zod";

import { transaction } from "~/components/database/index.server";

import { smtp } from "./modules";
import { mailOutbox } from "./schema.server";
import { smtpUrl, mailFrom, mailSendTimeout } from "./settings";
import { smtpSockets } from "./sockets.server";

export { smtpUrl, mailFrom, mailSendTimeout } from "./settings";

const message = z.strictObject({ to: z.string(), subject: z.string(), text: z.string() });

export declare namespace Mail {
  type Message = z.infer<typeof message>;
  type Sender = { send: (message: Message, options?: { signal?: AbortSignal }) => Promise<void> };
}

export const mail = resource({
  label: "mail.sender",
  depends: { url: smtpUrl, from: mailFrom, timeout: mailSendTimeout, smtp, sockets: smtpSockets },
  factory: async (
    { url, from, timeout, smtp, sockets },
    { defer, clock },
  ): Promise<Mail.Sender> => {
    const user = decodeURIComponent(url.username);
    const optionsForTransport = {
      host: url.hostname.replace(/^\[(.*)\]$/, "$1"),
      port: url.port ? Number(url.port) : undefined,
      secure: url.protocol === "smtps:" || url.port === "465",
      auth: user ? { user, pass: decodeURIComponent(url.password) } : undefined,
      pool: true,
      maxConnections: 1,
      getSocket: sockets.getSocket,
      dnsTimeout: timeout,
      connectionTimeout: timeout,
      greetingTimeout: timeout,
      socketTimeout: timeout,
    };
    let transport = smtp.default.createTransport(optionsForTransport);
    defer(() => transport.close());

    return {
      async send(message, options) {
        options?.signal?.throwIfAborted();

        const cancelled = Promise.withResolvers<never>();

        const abort = () => {
          sockets.abort();

          transport.close();

          transport = smtp.default.createTransport(optionsForTransport);

          cancelled.reject(options?.signal?.reason);
        };

        options?.signal?.addEventListener("abort", abort, { once: true });

        const timer = new AbortController();

        try {
          const sent = transport.sendMail({ from, ...message });

          const deadline = clock.sleep(timeout, timer.signal).then(() => {
            sockets.abort();

            transport.close();

            transport = smtp.default.createTransport(optionsForTransport);

            throw new Error("Mail send total timeout");
          });

          await Promise.race([sent, deadline, cancelled.promise]);
        } finally {
          timer.abort();

          options?.signal?.removeEventListener("abort", abort);
        }
      },
    };
  },
});

export const sendMail = operation({
  label: "sendMail",
  input: message,
  depends: { mail },
  run: async ({ mail }, { input, log }) => {
    await mail.send(input);
    log("mail.completed");
  },
});

/** The caller's write session owns this enqueue and its commit. */
export const enqueueMail = operation({
  label: "mail.enqueue",
  input: message,
  depends: { tx: transaction },
  run: async ({ tx }, { input, random }) => {
    await tx.insert(mailOutbox).values({ ...input, dedupeKey: `auth:${random.uuid()}` });
  },
});

/** Better Auth owns its pool writes; each callback awaits this separate durable call. */
export const authMail = resource({
  label: "mail.authWork",
  depends: { enqueue: enqueueMail },
  factory: ({ enqueue }, { closing }) => ({
    enqueue: (input: Mail.Message) => enqueue.run({ input, signal: closing }),
  }),
});

/** Missing mail config fails before the first send. */
export const mailStartup = extension({
  label: "mail",
  hooks: {
    start({ resolve, next }) {
      resolve(smtpUrl);
      resolve(mailFrom);
      return next();
    },
  },
});

import { resource } from "@tinker/core";

export const smtp = resource({
  label: "module:nodemailer",
  target: "scope",
  factory: () => import("nodemailer"),
});

/** SMTP owns these sockets so a total deadline can destroy an active send. */
export const smtpNet = resource({
  label: "module:node:net",
  target: "scope",
  factory: () => import("node:net"),
});

import type { Socket } from "node:net";

import { resource } from "@tinker/core";
import type { GetSocketCallback } from "nodemailer/lib/mailer";

import { smtpNet } from "./modules";
import { smtpUrl } from "./settings";

/** The SMTP pool owns protocol state; this resource owns its cancellable TCP sockets. */
export const smtpSockets = resource({
  label: "mail.sockets",
  depends: { net: smtpNet, url: smtpUrl },
  factory: async ({ net, url }, { defer }) => {
    const sockets = new Set<Socket>();
    defer(() => {
      for (const socket of sockets) socket.destroy();
    });
    return {
      getSocket(this: void, _options: unknown, callback: GetSocketCallback) {
        const socket = net.createConnection({
          host: url.hostname.replace(/^\[(.*)\]$/, "$1"),
          port: url.port ? Number(url.port) : url.protocol === "smtps:" ? 465 : 587,
        });

        sockets.add(socket);
        socket.on("error", () => {});
        socket.once("close", () => sockets.delete(socket));
        socket.once("error", callback);
        socket.once("connect", () => {
          socket.removeListener("error", callback);
          callback(null, { connection: socket });
        });
      },
      abort() {
        for (const socket of sockets) socket.destroy(new Error("Mail send total timeout"));
      },
    };
  },
});

import { tag } from "@tinker/core";
import { z } from "zod";

/** Where the SMTP server is, with its user and password when it needs them. */
export const smtpUrl = tag<URL>({ label: "mail.smtpUrl", parse: z.instanceof(URL) });

/** The sender address on each message. */
export const mailFrom = tag<string>({ label: "mail.from", parse: z.email() });

/** Total time for queueing and all SMTP stages, within the host grace. */
export const mailSendTimeout = tag<number>({
  label: "mail.sendTimeout",
  default: 3000,
  parse: z.number().int().positive().max(3000),
});

import { sql } from "drizzle-orm";
import { pgTable, bigserial, text, integer, timestamp, index } from "drizzle-orm/pg-core";

export const mailOutbox = pgTable(
  "mail_outbox",
  {
    id: bigserial({ mode: "number" }).primaryKey(),
    to: text().notNull(),
    subject: text().notNull(),
    text: text().notNull(),
    dedupeKey: text("dedupe_key").notNull().unique(),
    attempts: integer().notNull().default(0),
    nextAt: timestamp("next_at", { withTimezone: true }).notNull().defaultNow(),
    sentAt: timestamp("sent_at", { withTimezone: true }),
    lastError: text("last_error"),
    leaseToken: text("lease_token"),
    leaseUntil: timestamp("lease_until", { withTimezone: true }),
    deadAt: timestamp("dead_at", { withTimezone: true }),
  },
  (row) => [
    index("mail_outbox_due")
      .on(row.nextAt, row.id)
      .where(sql`${row.sentAt} is null and ${row.attempts} < 12`),
  ],
);

import { operation, resource, tag } from "@tinker/core";
import { z } from "zod";

import {
  transaction,
  database,
  drizzleOrm,
} from "~/components/database/index.server";

import { mail as alertMail } from "./mail.server";
import { mailOutbox } from "./schema.server";

/** Soft process stop: finish and commit the current SMTP send before closing the root. */
export const mailWorkerStop = tag<AbortSignal | undefined>({
  label: "outbox.stop",
  default: undefined,
});

/** A batch lease covers all twenty bounded sends and their acknowledgements. */
export const mailLeaseMs = tag<number>({
  label: "outbox.leaseMs",
  default: 180000,
  parse: z.number().int().min(1000).max(3600000),
});

export const claimMailBatch = operation({
  label: "outbox.claim",
  depends: { tx: transaction, orm: drizzleOrm, lease: mailLeaseMs },
  run: async ({ tx, orm, lease }, { clock, random }) => {
    const { and, or, lt, lte, isNull, asc, inArray, sql } = orm;
    const now = new Date(clock.currentTimeMillis());
    const available = or(isNull(mailOutbox.leaseUntil), lte(mailOutbox.leaseUntil, now));
    await tx
      .update(mailOutbox)
      .set({ deadAt: now, leaseToken: null, leaseUntil: null })
      .where(
        and(
          isNull(mailOutbox.sentAt),
          isNull(mailOutbox.deadAt),
          available,
          sql`${mailOutbox.attempts} >= 12`,
        ),
      );

    const token = random.uuid();
    const due = tx
      .select({ id: sql`${mailOutbox.id}` })
      .from(mailOutbox)
      .where(
        and(
          isNull(mailOutbox.sentAt),
          isNull(mailOutbox.deadAt),
          available,
          lt(mailOutbox.attempts, 12),
          lte(mailOutbox.nextAt, now),
        ),
      )
      .orderBy(asc(mailOutbox.nextAt), asc(mailOutbox.id))
      .limit(20)
      .for("update", { skipLocked: true });
    const rows = await tx
      .update(mailOutbox)
      .set({
        leaseToken: token,
        leaseUntil: new Date(now.getTime() + lease),
        attempts: sql`${mailOutbox.attempts} + 1`,
      })
      .where(inArray(mailOutbox.id, due))
      .returning();
    return { token, rows };
  },
});

export const acknowledgeMail = operation({
  label: "outbox.acknowledge",
  input: z.object({ id: z.number(), token: z.string(), error: z.string().nullable() }),
  depends: { tx: transaction, orm: drizzleOrm },
  run: async ({ tx, orm }, { input, clock, log }) => {
    const { and, eq, sql } = orm;
    const now = new Date(clock.currentTimeMillis());
    const [row] = await tx
      .update(mailOutbox)
      .set({
        leaseToken: null,
        leaseUntil: null,
        sentAt: input.error === null ? now : null,
        lastError: input.error,
        nextAt:
          input.error === null
            ? now
            : sql`${now}::timestamptz + least(1800000, 1000 * power(2, least(${mailOutbox.attempts} - 1, 11))) * interval '1 millisecond'`,
        deadAt:
          input.error === null
            ? null
            : sql`CASE WHEN ${mailOutbox.attempts} >= 12 THEN ${now}::timestamptz ELSE NULL END`,
      })
      .where(and(eq(mailOutbox.id, input.id), eq(mailOutbox.leaseToken, input.token)))
      .returning({ attempts: mailOutbox.attempts });
    if (row && input.error !== null) {
      log.error(row.attempts === 12 ? "outbox.dead" : "outbox.retry", {
        id: input.id,
        attempts: row.attempts,
      });
    }
    return { acknowledged: !!row };
  },
});

export const releaseMailClaims = operation({
  label: "outbox.releaseClaims",
  input: z.object({ token: z.string() }),
  depends: { tx: transaction, orm: drizzleOrm },
  run: async ({ tx, orm }, { input }) => {
    await tx
      .update(mailOutbox)
      .set({ leaseToken: null, leaseUntil: null })
      .where(orm.eq(mailOutbox.leaseToken, input.token));
  },
});

/** Native delivery integration: claim and ack each close before the next step. */
export const deliverMailBatch = operation({
  label: "outbox.deliverBatch",
  depends: {
    claim: claimMailBatch.controller,
    ack: acknowledgeMail.controller,
    release: releaseMailClaims.controller,
    mail: alertMail,
    stopping: mailWorkerStop,
  },
  run: async ({ claim, ack, release, mail, stopping }, { signal: contextSignal }) => {
    const signal = stopping ?? contextSignal;
    const { token, rows } = await claim.run({ signal: contextSignal });

    let sent = 0;
    let failed = 0;
    for (const row of rows) {
      if (signal.aborted) break;

      let error: string | null = null;

      try {
        await mail.send({ to: row.to, subject: row.subject, text: row.text });
      } catch (cause) {
        error = String(cause).slice(0, 1000);
      }
      const saved = await ack.run({ input: { id: row.id, token, error }, signal: contextSignal });

      if (!saved.acknowledged) continue;

      if (error === null) sent++;
      else failed++;
    }
    if (signal.aborted) {
      await release.run({ input: { token }, signal: contextSignal });
    }
    return { claimed: rows.length, sent, failed };
  },
});

/** LISTEN belongs to this resource; its private flag remembers wakes during a send. */
export const outboxWake = resource({
  label: "outbox.wake",
  depends: { database, stopping: mailWorkerStop },
  factory: async ({ database, stopping }, { clock, random, closing, defer, log }) => {
    const ending = stopping ? AbortSignal.any([closing, stopping]) : closing;
    let close: (() => void | Promise<void>) | undefined;
    let connected = false;
    let dirty = false;
    let failures = 0;
    let waiting: ReturnType<typeof Promise.withResolvers<void>> | undefined;
    defer(async () => {
      await close?.();
    });

    return {
      async listen() {
        if (connected) return;

        await close?.();
        close = undefined;
        ending.throwIfAborted();
        close = await database.listen("board_outbox", () => {
          dirty = true;
          waiting?.resolve();
        }, () => {
          connected = false;
          waiting?.resolve();
        }, ending);
        connected = true;
      },
      async retry() {
        // A failed connect must wait on the timer alone, never an old client's end event.
        const delay = Math.floor(
          Math.min(30_000, 1000 * 2 ** Math.min(failures, 5)) * (0.5 + random.next() / 2),
        );
        failures += 1;
        log("outbox.reconnect", { attempt: failures, delay });
        await clock.sleep(delay, ending).catch((error) => {
          if (!ending.aborted) throw error;
        });
      },
      async wait() {
        // A drop during a batch must return to listen instead of losing the wake for 30 seconds.
        if (dirty || !connected) {
          dirty = false;
          return;
        }
        failures = 0;

        const stop = new AbortController();
        waiting = Promise.withResolvers<void>();
        const tick = clock.sleep(30_000, AbortSignal.any([ending, stop.signal])).catch((error) => {
          if (!stop.signal.aborted && !ending.aborted) throw error;
        });

        try {
          await Promise.race([waiting.promise, tick]);
        } finally {
          waiting = undefined;
          stop.abort();
          await tick;
        }
        dirty = false;
      },
    };
  },
});

export const runMailWorker = operation({
  label: "mail.worker",
  depends: { deliver: deliverMailBatch.controller, wake: outboxWake, stopping: mailWorkerStop },
  run: async ({ deliver, wake, stopping }, { signal, log }) => {
    const stop = stopping ?? signal;
    while (!stop.aborted) {
      try {
        await wake.listen();
        let batch;
        do {
          batch = await deliver.run({ signal });
        } while (batch.claimed === 20 && !stop.aborted);
      } catch (error) {
        if (stop.aborted) return;
        log.error("outbox.unavailable", { error: String(error) });
        await wake.retry();
        continue;
      }
      if (!stop.aborted) await wake.wait();
    }
  },
});
